});</script><div id="onetrust-consent-sdk" data-nosnippet="true"><div class="onetrust-pc-dark-filter ot-hide ot-fade-in"></div><div id="onetrust-pc-sdk" class="otPcPanel ot-hide ot-fade-in otRelFont" lang="vi-VN" aria-label="Trung tâm ưu tiên" role="region"><div role="dialog" aria-modal="true" style="height: 100%;" aria-label="Cài đặt cookie"><!-- PC Header --><div class="ot-pc-header"><div class="ot-pc-logo" role="img" aria-label="Logo công ty"><img alt="Logo công ty" src="https://cdn.cookielaw.org/logos/10ddf4ca-c072-45d0-b3ac-eead0ed93db0/6e17f6e4-c77b-4a11-9f34-c107c42e4bfc/7981.png"></div><button id="close-pc-btn-handler" class="ot-close-icon" aria-label="Đóng" style="background-image: url(&quot;https://cdn.cookielaw.org/logos/static/ot_close.svg&quot;);"></button></div><div id="ot-pc-content" class="ot-pc-scrollbar"><div class="ot-optout-signal ot-hide"><div class="ot-optout-icon"><svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path class="ot-floating-button__svg-fill" d="M14.588 0l.445.328c1.807 1.303 3.961 2.533 6.461 3.688 2.015.93 4.576 1.746 7.682 2.446 0 14.178-4.73 24.133-14.19 29.864l-.398.236C4.863 30.87 0 20.837 0 6.462c3.107-.7 5.668-1.516 7.682-2.446 2.709-1.251 5.01-2.59 6.906-4.016zm5.87 13.88a.75.75 0 00-.974.159l-5.475 6.625-3.005-2.997-.077-.067a.75.75 0 00-.983 1.13l4.172 4.16 6.525-7.895.06-.083a.75.75 0 00-.16-.973z" fill="#FFF" fill-rule="evenodd"></path></svg></div><span></span></div><aside class="ot-h2" style="display: inline;"><h2 id="ot-pc-title">Cài đặt cookie</h2></aside><div id="ot-pc-desc">Chúng tôi và các đối tác bên thứ ba của chúng tôi (bao gồm các đối tác mạng xã hội, quảng cáo và phân tích) sử dụng cookie và các công nghệ theo dõi khác để thu thập, lưu trữ, theo dõi và xử lý một số thông tin nhất định về bạn khi bạn truy cập trang web của chúng tôi. Thông tin được thu thập có thể liên quan đến bạn, tùy chọn của bạn hoặc thiết bị của bạn. Chúng tôi sử dụng thông tin đó để làm cho trang web hoạt động, phân tích hiệu suất và lưu lượng truy cập trên trang web của chúng tôi, cung cấp trải nghiệm web được cá nhân hóa hơn và hỗ trợ nỗ lực tiếp thị của chúng tôi. Theo một số luật nhất định về quyền riêng tư, bạn có quyền hướng dẫn chúng tôi không "bán" hoặc "chia sẻ" thông tin cá nhân của bạn cho quảng cáo được nhắm mục tiêu. Để chọn không tham gia "bán" và "chia sẻ" thông tin cá nhân thông qua cookie, bạn phải chọn không sử dụng các cookie tùy chọn bằng cách sử dụng các nút gạt bên dưới. Để chọn không tham gia "bán" và "chia sẻ" dữ liệu được thu thập bằng các phương tiện khác (ví dụ: biểu mẫu trực tuyến), bạn cũng phải cập nhật tùy chọn chia sẻ dữ liệu của mình thông qua <a href="https://www.nvidia.com/en-us/about-nvidia/privacy-center/" target="_self">Trung tâm Tùy chọn NVIDIA</a>. Nhấp vào các tiêu đề danh mục khác nhau bên dưới để tìm hiểu thêm và thay đổi cài đặt theo tùy chọn của bạn. Bạn không thể chọn không sử dụng Cookie Bắt buộc vì chúng được triển khai để đảm bảo trang web của chúng tôi hoạt động chính xác (chẳng hạn như nhắc biểu ngữ cookie và ghi nhớ cài đặt của bạn, v.v.). Bằng cách nhấp vào "Lưu và chấp nhận" hoặc "Từ chối tất cả" ở phía dưới, bạn đồng ý với việc sử dụng cookie và các công cụ khác như được mô tả trong <a href="https://www.nvidia.com/vi-vn/about-nvidia/cookie-policy/" target="_self">Chính sách Cookie</a> của chúng tôi theo cài đặt của bạn và chấp nhận <a href="https://www.nvidia.com/en-us/about-nvidia/terms-of-service/" target="_self">Điều khoản dịch vụ</a> của chúng tôi (có chứa các miễn trừ quan trọng). Để biết thêm thông tin về các quy trình để bảo vệ quyền riêng tư của chúng tôi, vui lòng xem <a href="https://www.nvidia.com/en-us/about-nvidia/privacy-policy/" target="_self">Chính sách quyền riêng tư</a> của chúng tôi.</div><section class="ot-sdk-row ot-cat-grp"><!-- Non Accordion Group --><!-- Accordion Group section starts --><!-- Accordion Group section ends --><div class="ot-accordion-layout ot-cat-item ot-vs-config" data-optanongroupid="C0001"><button ot-accordion="true" aria-expanded="false" aria-controls="ot-desc-id-C0001" aria-labelledby="ot-header-id-C0001 ot-status-id-C0001"></button><!-- Accordion header --><div class="ot-acc-hdr ot-always-active-group"><div class="ot-plus-minus"><span></span><span></span></div><aside class="ot-h4 ot-cat-header" style="display: inline;"><h4 class="ot-cat-header" id="ot-header-id-C0001">Cookie Bắt Buộc</h4></aside><div id="ot-status-id-C0001" class="ot-always-active">Luôn luôn hoạt động</div></div><!-- accordion detail --><div class="ot-acc-grpcntr ot-acc-txt"><p class="ot-acc-grpdesc ot-category-desc" id="ot-desc-id-C0001">Những cookie này hỗ trợ chức năng chính như bảo mật, quản lý mạng và trợ năng. Không thể tắt các cookie này, trang web cần có chúng để hoạt động.</p><div class="ot-hlst-cntr"><button class="ot-link-btn category-host-list-handler" aria-label="Cookie Bắt Buộc - Nút Chi tiết Cookie mở menu Danh sách Cookie" data-parent-id="C0001">Chi tiết cookie‎</button></div></div></div><div class="ot-accordion-layout ot-cat-item ot-vs-config" data-optanongroupid="C0002"><button ot-accordion="true" aria-expanded="false" aria-controls="ot-desc-id-C0002" aria-labelledby="ot-header-id-C0002"></button><!-- Accordion header --><div class="ot-acc-hdr"><div class="ot-plus-minus"><span></span><span></span></div><aside class="ot-h4 ot-cat-header" style="display: inline;"><h4 class="ot-cat-header" id="ot-header-id-C0002">Cookie Hiệu Suất</h4></aside><div class="ot-tgl"><input type="checkbox" name="ot-group-id-C0002" id="ot-group-id-C0002" role="switch" class="category-switch-handler" data-optanongroupid="C0002" checked="" aria-labelledby="ot-header-id-C0002"> <label class="ot-switch" for="ot-group-id-C0002"><span class="ot-switch-nob"></span> <span class="ot-label-txt">Cookie Hiệu Suất</span></label> </div></div><!-- accordion detail --><div class="ot-acc-grpcntr ot-acc-txt"><p class="ot-acc-grpdesc ot-category-desc" id="ot-desc-id-C0002">Những cookie này được dùng để cung cấp các thước đo định lượng về khách truy cập trang web của chúng tôi, như số lần bạn truy cập, thời gian trên trang, chuyển động chuột, cuộn, nhấp chuột và hoạt động gõ phím trên trang web; hành vi duyệt, tìm kiếm hoặc nghiên cứu sản phẩm khác; và điều đã đưa bạn đến trang web của chúng tôi. Những cookie này có thể lưu trữ một ID duy nhất để hệ thống của chúng tôi sẽ ghi nhớ bạn khi bạn quay lại.  Thông tin được thu thập bằng các cookie này được sử dụng để đo lường và tìm cách cải thiện hiệu suất trang web.</p><div class="ot-hlst-cntr"><button class="ot-link-btn category-host-list-handler" aria-label="Cookie Hiệu Suất - Nút Chi tiết Cookie mở menu Danh sách Cookie" data-parent-id="C0002">Chi tiết cookie‎</button></div></div></div><div class="ot-accordion-layout ot-cat-item ot-vs-config" data-optanongroupid="C0003"><button ot-accordion="true" aria-expanded="false" aria-controls="ot-desc-id-C0003" aria-labelledby="ot-header-id-C0003"></button><!-- Accordion header --><div class="ot-acc-hdr"><div class="ot-plus-minus"><span></span><span></span></div><aside class="ot-h4 ot-cat-header" style="display: inline;"><h4 class="ot-cat-header" id="ot-header-id-C0003">Cookie Cá Nhân Hóa</h4></aside><div class="ot-tgl"><input type="checkbox" name="ot-group-id-C0003" id="ot-group-id-C0003" role="switch" class="category-switch-handler" data-optanongroupid="C0003" checked="" aria-labelledby="ot-header-id-C0003"> <label class="ot-switch" for="ot-group-id-C0003"><span class="ot-switch-nob"></span> <span class="ot-label-txt">Cookie Cá Nhân Hóa</span></label> </div></div><!-- accordion detail --><div class="ot-acc-grpcntr ot-acc-txt"><p class="ot-acc-grpdesc ot-category-desc" id="ot-desc-id-C0003">Những cookie này thu thập dữ liệu về cách bạn tương tác với trang web của chúng tôi để giúp chúng tôi cải thiện trải nghiệm web của bạn, chẳng hạn như những trang bạn đã truy cập. Những cookie này có thể lưu trữ một ID duy nhất để hệ thống của chúng tôi sẽ ghi nhớ bạn khi bạn quay lại.  Chúng có thể được thiết lập bởi chúng tôi hoặc bởi các nhà cung cấp bên thứ ba có dịch vụ mà chúng tôi đã thêm vào trang của mình. Những cookie này cho phép chúng tôi cung cấp chức năng nâng cao và cá nhân hóa trang web, cũng như giúp các thông điệp tiếp thị mà chúng tôi gửi cho bạn phù hợp hơn với sở thích của bạn. Nếu bạn không cho phép những cookie này thì một số hoặc tất cả các dịch vụ này có thể không hoạt động bình thường.</p><div class="ot-hlst-cntr"><button class="ot-link-btn category-host-list-handler" aria-label="Cookie Cá Nhân Hóa - Nút Chi tiết Cookie mở menu Danh sách Cookie" data-parent-id="C0003">Chi tiết cookie‎</button></div></div></div><div class="ot-accordion-layout ot-cat-item ot-vs-config" data-optanongroupid="C0004"><button ot-accordion="true" aria-expanded="false" aria-controls="ot-desc-id-C0004" aria-labelledby="ot-header-id-C0004"></button><!-- Accordion header --><div class="ot-acc-hdr"><div class="ot-plus-minus"><span></span><span></span></div><aside class="ot-h4 ot-cat-header" style="display: inline;"><h4 class="ot-cat-header" id="ot-header-id-C0004">Cookie Quảng Cáo</h4></aside><div class="ot-tgl"><input type="checkbox" name="ot-group-id-C0004" id="ot-group-id-C0004" role="switch" class="category-switch-handler" data-optanongroupid="C0004" checked="" aria-labelledby="ot-header-id-C0004"> <label class="ot-switch" for="ot-group-id-C0004"><span class="ot-switch-nob"></span> <span class="ot-label-txt">Cookie Quảng Cáo</span></label> </div></div><!-- accordion detail --><div class="ot-acc-grpcntr ot-acc-txt"><p class="ot-acc-grpdesc ot-category-desc" id="ot-desc-id-C0004">Những cookie này ghi lại lượt truy cập của bạn vào các trang web của chúng tôi, các trang bạn đã truy cập và các liên kết bạn đã theo dõi để tác động đến các quảng cáo mà bạn nhìn thấy trên các trang web khác. Những cookie này và thông tin họ thu thập có thể được quản lý bởi các công ty khác, bao gồm cả đối tác quảng cáo của chúng tôi và có thể được sử dụng để xây dựng hồ sơ về sở thích của bạn và hiển thị cho bạn quảng cáo có liên quan trên các trang web khác. Chúng tôi và các đối tác quảng cáo của chúng tôi sẽ sử dụng thông tin này để làm cho trang web của chúng tôi và quảng cáo hiển thị trên đó phù hợp hơn với sở thích của bạn.</p><div class="ot-hlst-cntr"><button class="ot-link-btn category-host-list-handler" aria-label="Cookie Quảng Cáo - Nút Chi tiết Cookie mở menu Danh sách Cookie" data-parent-id="C0004">Chi tiết cookie‎</button></div></div></div></section></div><section id="ot-pc-lst" class="ot-hide ot-pc-scrollbar"><div id="ot-pc-hdr"><div id="ot-lst-title"><button class="ot-link-btn back-btn-handler" aria-label="Back"><svg id="ot-back-arw" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" x="0px" y="0px" viewBox="0 0 444.531 444.531" xml:space="preserve"><title>Back Button</title><g><path fill="#656565" d="M213.13,222.409L351.88,83.653c7.05-7.043,10.567-15.657,10.567-25.841c0-10.183-3.518-18.793-10.567-25.835
